"""Own full original runtime to inspect trial input/reset/render focus semantics."""
from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download'
(o/'trialpage-original.js').write_bytes((r/'docs/replica/source/original.js').read_bytes())
script=r'''
const params=new URLSearchParams(location.search),states=[];let revision=0,index=0;if(params.has('reduced')){const style=document.createElement('style');style.textContent='.page *,.page *::before,.page *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}';document.head.append(style)}
const cases=[{english:false,ready:true,error:true},{english:true,ready:true,error:true},{english:false,ready:false,error:false},{english:true,ready:false,error:false},{english:true,ready:false,error:true,resume:true}];
function setup(){const c=cases[index];state=initial();state.screen='trial';lang=c.english?'en':'ko';state.trial.ready=c.ready;state.trial.consent=c.ready;if(c.resume){state.trial.host='owned-example';state.trial.db='owned-example';state.trial.validInput='owned-example';state.trial.invalidInput='owned-example'}state.error=c.error?t('시험 값과 기대 결과를 확인하세요.','Confirm trial inputs and expected outcomes.'):'';render();revision++;states.length=0;for(const node of document.querySelectorAll('[data-field^="trial."]'))node.dataset.probeRevision=String(revision);record()}
function read(){const box=e=>{const b=e.getBoundingClientRect();return{x:b.x,y:b.y,width:b.width,height:b.height}},consent=document.querySelector('[data-flag="trial.consent"]');return{case:index,english:lang==='en',trial:{...state.trial},error:state.error,revision,focus:document.activeElement?.id||document.activeElement?.dataset.flag||document.activeElement?.dataset.action||document.activeElement?.tagName,focusVisible:document.activeElement?.matches(':focus-visible')||false,fields:[...document.querySelectorAll('[data-field^="trial."]')].map(e=>({id:e.id,box:box(e),value:e.value,retained:e.dataset.probeRevision===String(revision),selectionStart:e.selectionStart})),tableRows:[...document.querySelectorAll('.page tbody>tr')].map(e=>({box:box(e),hover:e.matches(':hover'),background:getComputedStyle(e).backgroundColor,duration:getComputedStyle(e).transitionDuration,easing:getComputedStyle(e).transitionTimingFunction})),mainBox:box(document.getElementById('main')),footerBox:box(document.querySelector('.footer')),consent:{box:box(consent),checked:consent.checked},okVisible:!!document.querySelector('.notice.ok'),errorVisible:!!document.querySelector('.notice.error'),primary:{action:document.querySelector('.footer .primary')?.dataset.action,disabled:document.querySelector('.footer .primary')?.disabled},states:[...states]}}
let publishing=false;async function record(){if(publishing)return;publishing=true;try{const os=/Windows/.test(navigator.userAgent)?'windows':'mac';const response=await fetch('/evidence/home-trialpage-'+os+'-input.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(read())});if(!response.ok)throw Error('Record failed')}finally{publishing=false}}
document.getElementById('TrialPage-scroll').onclick=()=>{const main=document.getElementById('main');main.scrollTop=main.scrollTop<100?650:0;record()};
document.getElementById('TrialPage-consent-scroll').onclick=()=>{document.querySelector('[data-flag=\"trial.consent\"]').scrollIntoView({block:'center'});record()};
document.getElementById('TrialPage-next').onclick=()=>{index=(index+1)%cases.length;setup()};
for(const type of ['input','change','keydown','keyup','click'])document.addEventListener(type,e=>{if(!e.target.closest('#app'))return;const target=e.target.id||e.target.dataset.flag||e.target.dataset.action||e.target.tagName;setTimeout(()=>{const v=read();delete v.states;states.push({type,target,key:e.key,...v});record()},0)});
setup();setInterval(record,64);
'''
(o/'trialpage-input.html').write_text('<!doctype html><meta charset="utf-8"><title>TrialPage Input · original runtime</title><link rel="stylesheet" href="trialpage-original.css"><style>.utilities{position:fixed;right:0;top:0;z-index:200}</style><div id="app"></div><div id="dialog-host"></div><div id="toast-host"></div><div id="announcer" class="sr"></div><input id="file-open" type="file" hidden><div class="utilities"><button id="TrialPage-next" tabindex="-1">Trial setup next</button><button id="TrialPage-scroll" tabindex="-1">Trial scroll</button><button id="TrialPage-consent-scroll" tabindex="-1">Trial consent scroll</button></div><script src="trialpage-original.js"></script><script>'+script+'</script>')
print('Full original Trial runtime with passive focus-free observer prepared')
